+    fixture->eager = strcmp(argv[1], "eager") == 0;
+    fixture->nearfull = strcmp(argv[2], "nearfull") == 0;
+    fixture->graphs = strcmp(argv[3], "graph") == 0;
+    fixture->chain_eager = strcmp(argv[5], "eager") == 0;
